window.BANCO = window.BANCO || {};
window.BANCO.ciencias = [
{n:"f",t:"Sistema digestório",q:"Qual é o primeiro lugar do corpo por onde o alimento passa na digestão?",a:["A boca","O estômago","O esôfago","O intestino delgado"],c:0,e:"Tudo começa na boca! É lá que os dentes trituram o alimento e a saliva já começa a digestão."},
{n:"f",t:"Sistema digestório",q:"Qual órgão liga a faringe ao estômago?",a:["A traqueia","O esôfago","O intestino grosso","A laringe"],c:1,e:"O esôfago é como um tubo escorregadio que leva o alimento da garganta até o estômago. A traqueia é vizinha dele, mas serve para o ar."},
{n:"f",t:"Sistema digestório",q:"Em qual órgão o alimento é amassado e misturado ao suco gástrico?",a:["No fígado","Na boca","No estômago","No intestino grosso"],c:2,e:"O estômago é como uma batedeira: ele amassa o alimento e mistura tudo com o suco gástrico."},
{n:"f",t:"Sistema digestório",q:"Em qual órgão os nutrientes são absorvidos e passam para o sangue?",a:["No estômago","No esôfago","No intestino grosso","No intestino delgado"],c:3,e:"É no intestino delgado que a digestão termina e os nutrientes atravessam a parede do intestino e caem no sangue."},
{n:"f",t:"Sistema digestório",q:"O que o intestino grosso absorve do que sobrou da digestão?",a:["Água","Oxigênio","Bile","Saliva"],c:0,e:"O intestino grosso puxa a água que sobrou, como uma esponja. Por isso as fezes vão ficando mais firmes."},
{n:"f",t:"Sistema digestório",q:"Como se chama a massinha formada pelo alimento mastigado e misturado com a saliva?",a:["Suco gástrico","Bolo alimentar","Fezes","Bile"],c:1,e:"Depois de bem mastigado e umedecido pela saliva, o alimento vira uma massinha chamada bolo alimentar, pronta para ser engolida."},
{n:"f",t:"Sistema digestório",q:"Quais glândulas produzem a saliva?",a:["O fígado","O pâncreas","As glândulas salivares","O estômago"],c:2,e:"As glândulas salivares ficam na boca e produzem a saliva, que umedece o alimento e começa a digestão."},
{n:"f",t:"Sistema digestório",q:"Qual órgão produz a bile?",a:["O estômago","O pâncreas","O coração","O fígado"],c:3,e:"A bile é produzida pelo fígado e ajuda na digestão lá no intestino delgado. O pâncreas produz outro suco, o pancreático."},
{n:"f",t:"Sistema digestório",q:"Qual glândula produz o suco pancreático?",a:["O pâncreas","O fígado","A glândula salivar","O intestino delgado"],c:0,e:"O nome já dá a dica: suco pancreático vem do pâncreas! Ele ajuda a terminar a digestão no intestino delgado."},
{n:"f",t:"A mastigação",q:"Quais dentes servem para cortar os alimentos?",a:["Os molares","Os incisivos","Os caninos","Os pré-molares"],c:1,e:"Os incisivos ficam na frente da boca e funcionam como tesourinhas: cortam o pedaço do alimento na mordida."},
{n:"f",t:"A mastigação",q:"Quais dentes servem para rasgar e perfurar os alimentos?",a:["Os incisivos","Os molares","Os caninos","Os pré-molares"],c:2,e:"Os caninos são pontudos de propósito: eles rasgam e perfuram alimentos mais duros, como a carne."},
{n:"f",t:"A mastigação",q:"Quais dentes servem para triturar e moer os alimentos?",a:["Os caninos","Os incisivos","Os dentes de leite","Os molares e pré-molares"],c:3,e:"Os pré-molares e molares ficam no fundo da boca e são larguinhos, perfeitos para moer o alimento como um pilão."},
{n:"f",t:"A mastigação",q:"Quantos dentes tem a dentição de leite?",a:["20 dentes","32 dentes","12 dentes","28 dentes"],c:0,e:"A primeira dentição, a de leite, tem 20 dentes. Eles caem aos poucos para dar lugar aos permanentes."},
{n:"f",t:"A mastigação",q:"Quantos dentes tem a dentição permanente completa?",a:["20 dentes","32 dentes","36 dentes","24 dentes"],c:1,e:"A dentição permanente completa tem 32 dentes, 12 a mais que a de leite, porque a boca do adulto é maior."},
{n:"f",t:"A mastigação",q:"O que a saliva faz com o alimento na boca?",a:["Deixa o alimento gelado","Empurra o alimento até o estômago","Umedece e começa a digestão","Transforma o alimento em fezes"],c:2,e:"A saliva molha o alimento para facilitar a mastigação e já começa a digestão ali mesmo, na boca."},
{n:"f",t:"A mastigação",q:"Quem ajuda a misturar o alimento na boca e a empurrá-lo para a garganta?",a:["Os lábios","A epiglote","O nariz","A língua"],c:3,e:"A língua é super trabalhadora: mistura o alimento com a saliva e depois o empurra para a faringe na hora de engolir."},
{n:"f",t:"A mastigação",q:"Por que é importante mastigar bem os alimentos?",a:["Porque facilita a digestão","Porque deixa a comida mais gostosa","Porque limpa os dentes","Porque esfria a comida"],c:0,e:"Quanto mais triturado o alimento chega ao estômago, mais fácil fica a digestão. Mastigar bem é ajudar o estômago!"},
{n:"f",t:"A mastigação",q:"Qual é o líquido produzido na boca que ajuda na mastigação?",a:["A bile","A saliva","O suco gástrico","O suco pancreático"],c:1,e:"Na boca quem trabalha é a saliva. O suco gástrico fica no estômago, a bile vem do fígado e o suco pancreático, do pâncreas."},
{n:"f",t:"Sistema respiratório",q:"Por onde o ar deve entrar no nosso corpo?",a:["Pelos ouvidos","Pela epiglote","Pelas fossas nasais","Pelo esôfago"],c:2,e:"O ar entra pelas fossas nasais, os buraquinhos do nariz. Lá ele é filtrado, aquecido e umedecido antes de seguir viagem."},
{n:"f",t:"Sistema respiratório",q:"O que o nariz faz com o ar que entra?",a:["Esfria e seca o ar","Transforma o ar em gás carbônico","Empurra o ar para o estômago","Filtra, aquece e umedece o ar"],c:3,e:"O nariz é um porteiro caprichoso: filtra a poeira, esquenta e umedece o ar para ele chegar bem preparado aos pulmões."},
{n:"f",t:"Sistema respiratório",q:"Em quais órgãos esponjosos acontece a troca de gases da respiração?",a:["Nos pulmões","No coração","No estômago","Nos rins"],c:0,e:"Os pulmões são esponjosos e cheios de alvéolos. É lá que o oxigênio entra no sangue e o gás carbônico sai."},
{n:"f",t:"Sistema respiratório",q:"Como se chamam os saquinhos bem pequenos do pulmão onde ocorre a troca de gases?",a:["Bronquíolos","Alvéolos","Capilares","Átrios"],c:1,e:"Os alvéolos são saquinhos minúsculos, como cachinhos de uva. Neles o oxigênio passa para o sangue e o gás carbônico sai."},
{n:"f",t:"Sistema respiratório",q:"Qual tubo leva o ar da laringe até os brônquios?",a:["O esôfago","A faringe","A traqueia","O diafragma"],c:2,e:"A traqueia é um tubo com anéis, parecido com mangueira de aspirador, que conduz o ar até os brônquios."},
{n:"f",t:"Sistema respiratório",q:"Como se chama o movimento em que o ar ENTRA nos pulmões?",a:["Expiração","Digestão","Circulação","Inspiração"],c:3,e:"Quando o ar entra, é a inspiração. Quando sai, é a expiração. Dica: inspirar tem I de entrar o ar!"},
{n:"f",t:"Sistema respiratório",q:"Como se chama o movimento em que o ar SAI dos pulmões?",a:["Expiração","Inspiração","Deglutição","Mastigação"],c:0,e:"Soltar o ar é a expiração. É nela que jogamos para fora o gás carbônico que o corpo não quer."},
{n:"f",t:"Sistema respiratório",q:"Qual músculo fica abaixo dos pulmões e ajuda na respiração?",a:["O coração","O diafragma","A epiglote","O bíceps"],c:1,e:"O diafragma é um músculo em forma de chapéu embaixo dos pulmões. Ele sobe e desce para o ar entrar e sair."},
{n:"f",t:"Sistema respiratório",q:"Qual gás do ar o nosso corpo precisa pegar para viver?",a:["Gás carbônico","Hélio","Oxigênio","Vapor de água"],c:2,e:"Precisamos do oxigênio! Ele vai dos pulmões para o sangue e alimenta todas as células do corpo."},
{n:"f",t:"Sistema cardiovascular",q:"Qual órgão bombeia o sangue para o corpo todo?",a:["O pulmão","O cérebro","O fígado","O coração"],c:3,e:"O coração é como uma bomba que empurra o sangue sem parar para todas as partes do corpo."},
{n:"f",t:"Sistema cardiovascular",q:"O coração é formado principalmente por qual tipo de tecido?",a:["Um músculo","Um osso","Uma glândula","Um vaso sanguíneo"],c:0,e:"O coração é um músculo! Ele se aperta e relaxa o tempo todo para bombear o sangue, sem nunca tirar férias."},
{n:"f",t:"Sistema cardiovascular",q:"Quantas cavidades tem o coração?",a:["Duas","Quatro","Três","Seis"],c:1,e:"O coração tem 4 cavidades: 2 átrios em cima e 2 ventrículos embaixo, como uma casinha de 4 cômodos."},
{n:"f",t:"Sistema cardiovascular",q:"Quais vasos levam o sangue DO coração para o resto do corpo?",a:["Veias","Capilares","Artérias","Alvéolos"],c:2,e:"As artérias saem do coração levando o sangue para o corpo. Dica: Artéria = Anda para fora do coração."},
{n:"f",t:"Sistema cardiovascular",q:"Quais vasos trazem o sangue DE VOLTA ao coração?",a:["Artérias","Capilares","Bronquíolos","Veias"],c:3,e:"As veias fazem o caminho de volta: trazem o sangue do corpo de novo para o coração. Veia = Volta!"},
{n:"f",t:"Sistema cardiovascular",q:"Quais são os vasos bem fininhos que chegam a todas as partes do corpo?",a:["Os capilares","As artérias","As veias","As traqueias"],c:0,e:"Os capilares são fininhos como fios de cabelo, por isso o nome. Eles chegam pertinho de cada célula para fazer as entregas."},
{n:"f",t:"Sistema cardiovascular",q:"O que o sangue transporta para todas as células do corpo?",a:["Apenas água","Oxigênio e nutrientes","Saliva e bile","Fezes e urina"],c:1,e:"O sangue é como um caminhão de entregas: leva oxigênio e nutrientes para as células e ainda recolhe o gás carbônico."},
{n:"f",t:"Sistema cardiovascular",q:"O que estamos sentindo quando tocamos o pulso no punho?",a:["A digestão","A respiração","Os batimentos do coração","Os movimentos peristálticos"],c:2,e:"O pulso é a batida do coração que sentimos na artéria do punho. Cada tum-tum do coração empurra o sangue e faz o pulso pulsar."},
{n:"f",t:"Sistema digestório",q:"Qual é a última parte do tubo digestório, por onde as fezes saem do corpo?",a:["A faringe","O esôfago","O estômago","O ânus"],c:3,e:"O ânus é a saída do tubo digestório. É por ele que o corpo elimina as fezes, ou seja, aquilo que não deu para aproveitar."},
{n:"f",t:"Sistema digestório",q:"Como se chama o que sobra da digestão e é eliminado pelo corpo?",a:["Bolo alimentar","Bile","Fezes","Nutrientes"],c:2,e:"O que o corpo não aproveita vira fezes, formadas no intestino grosso. O bolo alimentar é o alimento no começo do caminho, ainda cheio de nutrientes."},
{n:"f",t:"Sistema digestório",q:"Qual órgão o alimento atravessa logo depois de sair da boca?",a:["O estômago","O intestino grosso","A traqueia","A faringe"],c:3,e:"Depois da boca o alimento passa pela faringe, que é a nossa garganta, e só então entra no esôfago."},
{n:"f",t:"Sistema digestório",q:"Como se chamam os movimentos que empurram o alimento pelo tubo digestório?",a:["Movimentos respiratórios","Batimentos cardíacos","Movimentos peristálticos","Movimentos de mastigação"],c:2,e:"Os movimentos peristálticos são ondinhas de músculo que empurram o alimento, parecido com apertar um tubo de pasta de dente."},
{n:"f",t:"Sistema digestório",q:"Em qual órgão é produzido o suco gástrico?",a:["No esôfago","No fígado","No pâncreas","No estômago"],c:3,e:"O suco gástrico é feito pelas paredes do próprio estômago e ajuda a quebrar o alimento em pedacinhos bem pequenos."},
{n:"f",t:"Sistema digestório",q:"Qual parte do intestino é mais comprida e mais fininha?",a:["O intestino grosso","O esôfago","O intestino delgado","O ânus"],c:2,e:"O intestino delgado é bem mais comprido e mais fino que o grosso. Todo enroladinho na barriga, ele mede vários metros!"},
{n:"f",t:"Sistema digestório",q:"Fígado, pâncreas e glândulas salivares são exemplos de quê no sistema digestório?",a:["Ossos","Vasos sanguíneos","Músculos","Glândulas anexas"],c:3,e:"Essas três são glândulas anexas: o alimento não passa dentro delas, mas elas mandam sucos que ajudam na digestão."},
{n:"f",t:"Sistema digestório",q:"Para que serve o sistema digestório?",a:["Para bombear o sangue","Para produzir os batimentos do coração","Para levar o ar até os pulmões","Para transformar o alimento em nutrientes que o corpo aproveita"],c:3,e:"O sistema digestório desmonta o alimento até virar nutrientes bem pequenininhos, que o sangue consegue levar para o corpo todo."},
{n:"f",t:"Sistema digestório",q:"Em qual órgão as fezes são formadas?",a:["No estômago","No intestino delgado","No intestino grosso","No fígado"],c:2,e:"No intestino grosso a água é absorvida e o que resta vira as fezes, que ficam guardadas ali até a hora de ir ao banheiro."},
{n:"f",t:"A mastigação",q:"Em que parte da boca ficam os dentes incisivos?",a:["Embaixo da língua","No fundo de cima","No fundo de baixo","Na frente"],c:3,e:"Os incisivos são os dentes da frente, aqueles que aparecem quando sorrimos. É com eles que damos a primeira mordida."},
{n:"f",t:"A mastigação",q:"Como se chama o problema que abre buraquinhos nos dentes quando não escovamos bem?",a:["Gripe","Cãibra","Cárie","Azia"],c:2,e:"A cárie aparece quando restos de comida e bactérias ficam no dente e vão estragando o esmalte. Escovar os dentes espanta esse problema. 🦷"},
{n:"f",t:"A mastigação",q:"O que devemos fazer depois das refeições para cuidar bem dos dentes?",a:["Tomar refrigerante","Comer uma bala","Escovar os dentes","Dormir na mesma hora"],c:2,e:"Escovar os dentes depois de comer tira os restos de alimento que servem de comida para as bactérias da cárie."},
{n:"f",t:"A mastigação",q:"Qual dente pontudo fica entre os incisivos e os pré-molares?",a:["O molar","O dente do siso","O incisivo lateral","O canino"],c:3,e:"O canino é aquele dente pontudinho do cantinho da boca. O nome vem dos cachorros, que têm caninos bem grandes para rasgar a carne."},
{n:"f",t:"A mastigação",q:"Como se chama o ato de triturar o alimento com os dentes?",a:["Absorção","Respiração","Circulação","Mastigação"],c:3,e:"Mastigar é triturar o alimento com os dentes. Esse é o primeiro passo da digestão e acontece na boca."},
{n:"f",t:"A mastigação",q:"Qual é a camada dura e branquinha que protege o dente por fora?",a:["A gengiva","A raiz","A saliva","O esmalte"],c:3,e:"O esmalte é a parte mais dura do corpo e funciona como uma capa de proteção. Quando ele se desgasta, a cárie consegue entrar."},
{n:"f",t:"A mastigação",q:"Os dentes de leite caem para dar lugar a quais dentes?",a:["A novos dentes de leite","A nenhum outro dente","Aos dentes permanentes","Somente aos caninos"],c:2,e:"Os 20 dentes de leite caem aos poucos e, no lugar deles, nascem os dentes permanentes, que precisam durar a vida inteira."},
{n:"f",t:"A mastigação",q:"Além da escova, o que usamos para limpar entre um dente e outro?",a:["O algodão","O palito de churrasco","O guardanapo","O fio dental"],c:3,e:"O fio dental entra naqueles espacinhos onde a escova não alcança. Usar os dois é o combo perfeito contra a cárie."},
{n:"f",t:"Sistema respiratório",q:"Qual órgão faz parte do sistema respiratório e também do sistema digestório?",a:["Os alvéolos","A traqueia","O esôfago","A faringe"],c:3,e:"A faringe é a nossa garganta e é caminho tanto do ar quanto do alimento. Por isso ela é comum aos dois sistemas."},
{n:"f",t:"Sistema respiratório",q:"Em qual órgão do caminho do ar ficam as cordas vocais?",a:["Na traqueia","Nos brônquios","Na laringe","Nas fossas nasais"],c:2,e:"A laringe guarda as cordas vocais. Quando o ar passa por elas, nasce a voz e conseguimos falar e cantar."},
{n:"f",t:"Sistema respiratório",q:"Em quantos brônquios a traqueia se divide?",a:["Dez","Um","Quatro","Dois"],c:3,e:"A traqueia se divide em dois brônquios, um para cada pulmão, formando um Y de cabeça para baixo."},
{n:"f",t:"Sistema respiratório",q:"Como se chamam os tubinhos bem finos em que os brônquios se dividem dentro do pulmão?",a:["Capilares","Alvéolos","Átrios","Bronquíolos"],c:3,e:"Os brônquios se dividem em bronquíolos, canudinhos cada vez mais finos, como os galhos de uma árvore."},
{n:"f",t:"Sistema respiratório",q:"Qual gás o corpo elimina quando soltamos o ar?",a:["Oxigênio","Vapor de gasolina","Gás carbônico","Gás de cozinha"],c:2,e:"Na expiração jogamos fora o gás carbônico, que é o resto produzido pelas células e que o corpo não quer mais."},
{n:"f",t:"Sistema respiratório",q:"Quantos pulmões uma pessoa tem?",a:["Um","Três","Dois","Quatro"],c:2,e:"Temos dois pulmões, um do lado direito e outro do lado esquerdo do tórax, com o coração no meio deles."},
{n:"f",t:"Sistema respiratório",q:"Qual estrutura fecha a entrada da traqueia quando engolimos?",a:["O alvéolo","A língua","O diafragma","A epiglote"],c:3,e:"A epiglote funciona como uma tampinha: na hora de engolir ela fecha a traqueia para o alimento seguir pelo esôfago."},
{n:"f",t:"Sistema respiratório",q:"Para que serve o sistema respiratório?",a:["Para formar as fezes","Para triturar o alimento","Para pegar oxigênio do ar e eliminar gás carbônico","Para produzir a saliva"],c:2,e:"Respirar serve para trazer oxigênio para dentro do corpo e colocar o gás carbônico para fora. É uma troca!"},
{n:"f",t:"Sistema respiratório",q:"Para que servem os pelinhos e o muco de dentro do nariz?",a:["Para esfriar o ar","Para bombear o sangue","Para produzir a voz","Para segurar a poeira e a sujeira do ar"],c:3,e:"Os pelinhos e o muco funcionam como o filtro de um aspirador: prendem a poeira para ela não chegar aos pulmões."},
{n:"f",t:"Sistema cardiovascular",q:"Como se chamam as duas cavidades de cima do coração?",a:["Ventrículos","Alvéolos","Átrios","Brônquios"],c:2,e:"As duas cavidades de cima são os átrios e as de baixo são os ventrículos. Dica: átrio lembra o andar de cima."},
{n:"f",t:"Sistema cardiovascular",q:"Como se chamam as duas cavidades de baixo do coração?",a:["Átrios","Capilares","Ventrículos","Bronquíolos"],c:2,e:"Embaixo ficam os ventrículos. Eles são mais fortes porque precisam empurrar o sangue para bem longe."},
{n:"f",t:"Sistema cardiovascular",q:"Em que parte do corpo fica o coração?",a:["Dentro da cabeça","Na barriga, perto do estômago","Dentro do pescoço","No tórax, entre os pulmões"],c:3,e:"O coração fica no tórax, entre os dois pulmões, um pouquinho mais para o lado esquerdo. É por isso que sentimos as batidas ali."},
{n:"f",t:"Sistema cardiovascular",q:"Qual gás o sangue recolhe das células para levar até os pulmões?",a:["Oxigênio","Vapor de água","Hélio","Gás carbônico"],c:3,e:"O sangue entrega oxigênio e, na volta, carrega o gás carbônico até os pulmões para ser eliminado na expiração."},
{n:"f",t:"Sistema cardiovascular",q:"O sistema cardiovascular é formado pelo coração e por quais estruturas?",a:["Pelos ossos","Pelos dentes","Pelos pulmões","Pelos vasos sanguíneos"],c:3,e:"O sistema cardiovascular é o coração mais os vasos sanguíneos: artérias, veias e capilares, que são as estradas do sangue."},
{n:"f",t:"Sistema cardiovascular",q:"O coração de uma pessoa tem mais ou menos o tamanho de quê?",a:["De uma bola de futebol","De um grão de arroz","Do seu próprio punho fechado","De um travesseiro"],c:2,e:"O coração tem mais ou menos o tamanho do punho fechado da própria pessoa. Pequeno, mas muito forte!"},
{n:"f",t:"Sistema cardiovascular",q:"Como se chama cada batida do coração?",a:["Movimento peristáltico","Inspiração","Batimento cardíaco","Mastigação"],c:2,e:"Cada aperto do coração é um batimento cardíaco. É ele que empurra o sangue e que sentimos como pulso."},
{n:"f",t:"Sistema cardiovascular",q:"Além do punho, em que outro lugar é fácil sentir o pulso?",a:["No cotovelo","No cabelo","Na unha","No pescoço"],c:3,e:"No pescoço passa uma artéria grande e dá para sentir o pulso ali, encostando os dedinhos de leve ao lado do gogó."},
{n:"f",t:"Sistema cardiovascular",q:"O que acontece com o coração enquanto dormimos?",a:["Ele para de bater","Ele descansa por algumas horas","Ele bate muito mais rápido do que acordado","Ele continua batendo, só um pouco mais devagar"],c:3,e:"O coração nunca para: durante o sono ele bate mais devagarzinho, porque o corpo está em repouso e precisa de menos oxigênio."},
{n:"m",t:"Sistema digestório",q:"Qual é a ordem correta do caminho do alimento no corpo?",a:["Boca, esôfago, faringe, estômago, intestinos","Boca, estômago, esôfago, intestino grosso, intestino delgado","Boca, faringe, esôfago, estômago, intestino delgado, intestino grosso","Boca, traqueia, estômago, intestino delgado, ânus"],c:2,e:"O alimento desce sempre nessa ordem: boca, faringe, esôfago, estômago, intestino delgado e intestino grosso. A traqueia não entra nessa lista, porque ela é caminho do ar."},
{n:"m",t:"Sistema digestório",q:"Para onde o alimento vai logo depois de sair do estômago?",a:["Para o intestino grosso","Para o esôfago","Para o intestino delgado","Para o fígado"],c:2,e:"Do estômago o alimento segue para o intestino delgado, onde a digestão termina e os nutrientes são absorvidos. O intestino grosso só vem depois."},
{n:"m",t:"Sistema digestório",q:"Depois do intestino delgado, para onde vai o que não foi absorvido?",a:["Para o intestino grosso","Para o estômago","Para o pâncreas","Para a boca"],c:0,e:"O que não foi absorvido segue para o intestino grosso, que puxa a água que sobrou e forma as fezes."},
{n:"m",t:"Sistema digestório",q:"Em qual órgão a bile produzida pelo fígado é lançada para ajudar na digestão?",a:["No estômago","No esôfago","No intestino grosso","No intestino delgado"],c:3,e:"O fígado fabrica a bile, mas ela vai trabalhar no intestino delgado. É lá que a digestão termina, com a ajuda da bile e do suco pancreático."},
{n:"m",t:"Sistema digestório",q:"Qual destas é a função do intestino grosso?",a:["Produzir a bile","Produzir o suco gástrico","Absorver os nutrientes para o sangue","Absorver a água e formar as fezes"],c:3,e:"O intestino grosso é o setor da água: ele absorve o que sobrou de líquido e forma as fezes. Quem absorve os nutrientes é o intestino delgado."},
{n:"m",t:"Sistema digestório",q:"O que a bile faz na digestão?",a:["Ajuda a digerir as gorduras","Mastiga o alimento","Forma as fezes","Transporta oxigênio"],c:0,e:"A bile age como um detergente: ela quebra as gotas de gordura em gotinhas menores para o corpo conseguir digeri-las."},
{n:"m",t:"Sistema digestório",q:"Se uma pessoa come deitada, o alimento ainda chega ao estômago. Por quê?",a:["Porque o alimento cai pela gravidade","Porque o coração bombeia o alimento","Porque os movimentos peristálticos empurram o alimento","Porque a saliva empurra o alimento"],c:2,e:"Não é a gravidade que faz o alimento descer: os músculos do esôfago se apertam em ondinhas, os movimentos peristálticos, e empurram o bolo alimentar."},
{n:"m",t:"Sistema digestório",q:"Qual órgão do sistema digestório é uma bolsa de paredes musculosas?",a:["O esôfago","O fígado","O estômago","O pâncreas"],c:2,e:"O estômago é uma bolsa com paredes de músculo. Elas se apertam para revirar o alimento e misturá-lo com o suco gástrico."},
{n:"m",t:"Sistema digestório",q:"Qual órgão recebe o alimento que desce pelo esôfago?",a:["O estômago","O intestino delgado","A faringe","O fígado"],c:0,e:"O esôfago é um corredor que termina no estômago. É lá que o alimento fica um tempo sendo revirado e transformado."},
{n:"m",t:"A mastigação",q:"Ao dar a primeira mordida em uma maçã, quais dentes você usa?",a:["Os molares","Os pré-molares","Os caninos","Os incisivos"],c:3,e:"A primeira mordida é feita pelos incisivos, os dentes da frente, que cortam o pedaço como uma tesourinha."},
{n:"m",t:"A mastigação",q:"Para rasgar um pedaço de carne mais durinha, quais dentes ajudam mais?",a:["Os incisivos","Os molares","Os caninos","Os dentes de leite"],c:2,e:"Os caninos são pontudos e servem exatamente para rasgar e perfurar alimentos mais resistentes, como a carne."},
{n:"m",t:"A mastigação",q:"Depois de cortar o alimento, quais dentes fazem o trabalho de moer bem no fundo da boca?",a:["Os pré-molares e os molares","Só os incisivos","Só os caninos","Os incisivos e os caninos"],c:0,e:"Os pré-molares e molares têm a superfície larga e cheia de saliências, perfeita para moer o alimento como um pilão."},
{n:"m",t:"A mastigação",q:"Por que a saliva é importante na hora de engolir?",a:["Porque esfria o alimento","Porque absorve os nutrientes","Porque umedece o alimento e ajuda a formar o bolo alimentar","Porque produz as fezes"],c:2,e:"A saliva molha o alimento e o transforma numa massinha escorregadia, o bolo alimentar, que desce com facilidade pelo esôfago."},
{n:"m",t:"A mastigação",q:"Se a dentição de leite tem 20 dentes e a permanente tem 32, quantos dentes a mais aparecem na permanente?",a:["10 dentes","52 dentes","20 dentes","12 dentes"],c:3,e:"32 menos 20 dá 12 dentes a mais. Eles aparecem porque a boca cresce e cabem mais dentes de trituração no fundo."},
{n:"m",t:"A mastigação",q:"O que costuma acontecer quando alguém engole a comida quase sem mastigar?",a:["A digestão fica mais rápida e fácil","O alimento é absorvido logo na boca","O estômago tem mais trabalho e a digestão fica mais difícil","A saliva para de ser produzida"],c:2,e:"Pedaços grandes dão muito mais trabalho ao estômago. Mastigar bem é como picar os ingredientes antes de cozinhar: facilita todo o resto."},
{n:"m",t:"A mastigação",q:"Qual destes hábitos ajuda de verdade a evitar cáries?",a:["Beber refrigerante nas refeições","Comer doce antes de dormir","Mastigar chiclete com açúcar","Escovar os dentes e passar fio dental todos os dias"],c:3,e:"A dupla escova mais fio dental tira os restos de comida que as bactérias usariam para atacar o dente."},
{n:"m",t:"A mastigação",q:"Qual é a ordem do que acontece com o alimento dentro da boca?",a:["Os dentes trituram, a saliva umedece e a língua empurra para a faringe","A língua empurra, depois os dentes trituram e a saliva seca o alimento","O alimento é absorvido e só depois mastigado","A saliva forma as fezes e os dentes cortam"],c:0,e:"Primeiro os dentes trituram, a saliva umedece e começa a digestão, e por fim a língua empurra o bolo alimentar para a faringe."},
{n:"m",t:"Sistema respiratório",q:"Qual é a ordem correta do caminho do ar até os pulmões?",a:["Fossas nasais, esôfago, traqueia, pulmões","Boca, estômago, brônquios, alvéolos","Fossas nasais, faringe, laringe, traqueia, brônquios, alvéolos","Traqueia, laringe, faringe, fossas nasais, alvéolos"],c:2,e:"O ar entra pelas fossas nasais e segue por faringe, laringe, traqueia, brônquios, bronquíolos até os alvéolos. O esôfago não participa: ele é do alimento."},
{n:"m",t:"Sistema respiratório",q:"Coloque em ordem: por onde o ar passa primeiro, depois e por último entre laringe, brônquios e traqueia?",a:["Laringe, traqueia, brônquios","Traqueia, laringe, brônquios","Brônquios, traqueia, laringe","Traqueia, brônquios, laringe"],c:0,e:"Descendo pela garganta, o ar passa pela laringe, entra na traqueia e só depois se divide nos dois brônquios."},
{n:"m",t:"Sistema respiratório",q:"Depois de passar pelos bronquíolos, onde o ar chega?",a:["Na traqueia","Na laringe","Nos alvéolos","No esôfago"],c:2,e:"Os bronquíolos terminam nos alvéolos, os saquinhos onde acontece a troca de gases. Fim da linha para o ar!"},
{n:"m",t:"Sistema respiratório",q:"O que o diafragma faz durante a inspiração?",a:["Ele sobe e aperta os pulmões","Ele bombeia o sangue","Ele fecha a traqueia","Ele desce e o tórax aumenta de espaço"],c:3,e:"Na inspiração o diafragma abaixa, o tórax fica com mais espaço e o ar entra correndo para preencher os pulmões."},
{n:"m",t:"Sistema respiratório",q:"O que o diafragma faz durante a expiração?",a:["Ele sobe e o ar é empurrado para fora","Ele desce e puxa mais ar","Ele fica totalmente parado","Ele produz o gás carbônico"],c:0,e:"Na expiração o diafragma sobe, o espaço do tórax diminui e o ar com gás carbônico é empurrado para fora."},
{n:"m",t:"Sistema respiratório",q:"O que entra e o que sai do sangue dentro dos alvéolos?",a:["Entra gás carbônico e sai oxigênio","Entram nutrientes e sai água","Entra oxigênio e sai gás carbônico","Entra saliva e sai bile"],c:2,e:"Nos alvéolos o oxigênio do ar passa para o sangue e o gás carbônico faz o caminho contrário, para ser eliminado na expiração."},
{n:"m",t:"Sistema respiratório",q:"Qual destes órgãos NÃO faz parte do sistema respiratório?",a:["A traqueia","Os brônquios","A laringe","O esôfago"],c:3,e:"O esôfago é do sistema digestório: ele leva alimento, não ar. Traqueia, brônquios e laringe são todos caminho do ar."},
{n:"m",t:"Sistema respiratório",q:"Quando respiramos pela boca em vez do nariz, o que o corpo deixa de fazer com o ar?",a:["Filtrar, aquecer e umedecer o ar","Encher os pulmões de ar","Eliminar o gás carbônico","Fazer a troca nos alvéolos"],c:0,e:"Só o nariz filtra, aquece e umedece o ar. Pela boca o ar chega mais frio, seco e sujo aos pulmões."},
{n:"m",t:"Sistema respiratório",q:"Ao soprar as velinhas do bolo de aniversário, qual movimento respiratório usamos?",a:["A inspiração","A digestão","A expiração","O batimento cardíaco"],c:2,e:"Soprar é expirar: o ar sai dos pulmões. Antes disso a gente inspira fundo para encher o peito de ar. 🎂"},
{n:"m",t:"Sistema cardiovascular",q:"O sangue sai do coração por quais vasos e volta por quais?",a:["Sai pelas veias e volta pelas artérias","Sai pelos capilares e volta pelos alvéolos","Sai pelas artérias e volta pelas veias","Sai e volta somente pelos capilares"],c:2,e:"Artéria é a estrada de ida (sai do coração) e veia é a estrada de volta (traz o sangue de novo para o coração)."},
{n:"m",t:"Sistema cardiovascular",q:"Em qual órgão o sangue pega o oxigênio que vai distribuir para o corpo?",a:["No estômago","No intestino delgado","No fígado","Nos pulmões"],c:3,e:"O sangue passa pelos pulmões e, nos alvéolos, carrega o oxigênio. Depois volta ao coração para ser bombeado ao corpo todo."},
{n:"m",t:"Sistema cardiovascular",q:"Depois de pegar oxigênio nos pulmões, para onde o sangue vai?",a:["Volta ao coração, que o bombeia para o corpo","Vai direto para o estômago","Volta para os alvéolos","Fica guardado nos pulmões"],c:0,e:"O sangue cheio de oxigênio volta ao coração e é bombeado com força para o corpo inteiro. O coração é a estação central."},
{n:"m",t:"Sistema cardiovascular",q:"Qual é a função dos ventrículos do coração?",a:["Receber o sangue que chega","Filtrar o ar que respiramos","Empurrar o sangue para fora do coração","Produzir os nutrientes"],c:2,e:"Os ventrículos são as cavidades de baixo e funcionam como bombas: apertam com força e mandam o sangue para fora do coração."},
{n:"m",t:"Sistema cardiovascular",q:"Qual é a função dos átrios do coração?",a:["Empurrar o sangue para o corpo","Fazer a troca de gases","Receber o sangue que chega ao coração","Produzir a bile"],c:2,e:"Os átrios são as salas de espera do coração: recebem o sangue que chega pelas veias e o passam para os ventrículos."},
{n:"m",t:"Sistema cardiovascular",q:"Quantos batimentos por minuto costuma ter o coração de uma criança em repouso?",a:["Cerca de 5","Cerca de 1000","Cerca de 500","Entre 70 e 100"],c:3,e:"Em repouso, o coração de uma criança bate mais ou menos de 70 a 100 vezes por minuto. Quando ela corre, esse número sobe bastante."},
{n:"m",t:"Sistema cardiovascular",q:"Em qual vaso o sangue corre com mais força, logo depois de sair do coração?",a:["Na veia","No capilar","No bronquíolo","Na artéria"],c:3,e:"Ao sair do coração o sangue entra nas artérias com muita pressão. É essa forcinha que sentimos como pulso."},
{n:"m",t:"Sistema cardiovascular",q:"Em quais vasos acontece a entrega de oxigênio e nutrientes para as células?",a:["Nos capilares","Nas veias grossas","Nos brônquios","Nos átrios"],c:0,e:"Os capilares são tão fininhos e chegam tão perto das células que é neles que a entrega acontece, como um entregador de bicicleta na ruazinha estreita."},
{n:"m",t:"Sistema cardiovascular",q:"Qual é a diferença principal entre uma artéria e uma veia?",a:["A artéria transporta ar e a veia transporta sangue","A artéria fica só no braço e a veia só na perna","A artéria leva o sangue do coração e a veia traz o sangue de volta","A artéria é mais fina que o capilar"],c:2,e:"A diferença é a direção do caminho: artéria leva o sangue para fora do coração e veia traz de volta. As duas transportam sangue."},
{n:"m",t:"Sistema digestório",q:"Depois de absorvidos no intestino delgado, quem leva os nutrientes para todas as partes do corpo?",a:["A saliva","A bile","O ar dos pulmões","O sangue"],c:3,e:"Os nutrientes entram no sangue e o coração se encarrega de bombeá-los para o corpo todo. O sangue é o entregador do corpo."},
{n:"m",t:"Sistema digestório",q:"Em qual órgão o alimento fica algumas horas sendo revirado até virar uma papa?",a:["No esôfago","Na faringe","No estômago","No intestino grosso"],c:2,e:"No estômago o alimento fica horas sendo batido pelas paredes musculosas e misturado ao suco gástrico, até virar uma papa."},
{n:"m",t:"Sistema digestório",q:"O que a saliva, o suco gástrico e o suco pancreático têm em comum?",a:["Todos ajudam a digerir o alimento","Todos são produzidos no estômago","Todos transportam oxigênio","Todos formam as fezes"],c:0,e:"São três sucos digestivos: cada um age em um lugar diferente, mas todos ajudam a desmontar o alimento em nutrientes."},
{n:"m",t:"Sistema digestório",q:"Qual glândula anexa do sistema digestório fica na boca?",a:["O fígado","O pâncreas","O estômago","As glândulas salivares"],c:3,e:"As glândulas salivares ficam na boca e já mandam a saliva para o alimento assim que começamos a mastigar."},
{n:"m",t:"Sistema digestório",q:"Por dentro de qual destes órgãos o alimento NÃO passa?",a:["Pelo fígado","Pelo estômago","Pelo esôfago","Pelo intestino delgado"],c:0,e:"O fígado é uma glândula anexa: o alimento não entra nele. Ele apenas manda a bile para o intestino delgado."},
{n:"m",t:"Sistema digestório",q:"Entre esôfago, estômago, intestino delgado e intestino grosso, qual o alimento alcança por último?",a:["O esôfago","O estômago","O intestino delgado","O intestino grosso"],c:3,e:"A ordem é esôfago, estômago, intestino delgado e, por último, intestino grosso. Depois dele só falta a saída pelo ânus."},
{n:"m",t:"Sistema digestório",q:"Quais são as glândulas anexas do sistema digestório?",a:["Pulmões, coração e rins","Estômago, intestino delgado e intestino grosso","Glândulas salivares, fígado e pâncreas","Faringe, laringe e traqueia"],c:2,e:"São três: glândulas salivares (saliva), fígado (bile) e pâncreas (suco pancreático). Elas ajudam sem que o alimento passe dentro delas."},
{n:"m",t:"Sistema digestório",q:"Por que precisamos comer todos os dias?",a:["Para conseguir nutrientes que dão energia e ajudam o corpo a crescer","Para produzir mais saliva","Para encher o intestino grosso","Para respirar melhor"],c:0,e:"O alimento é o combustível e também o material de construção do corpo: dá energia para brincar e ajuda a crescer e a se recuperar."},
{n:"m",t:"Sistema digestório",q:"Qual é a ordem em que estes sucos agem sobre o alimento?",a:["Suco gástrico, saliva, suco pancreático","Suco pancreático, suco gástrico, saliva","Saliva, suco gástrico, suco pancreático","Saliva, suco pancreático, suco gástrico"],c:2,e:"Primeiro a saliva, na boca. Depois o suco gástrico, no estômago. Por último o suco pancreático, no intestino delgado."},
{n:"m",t:"A mastigação",q:"Quantos tipos diferentes de dentes existem na dentição permanente?",a:["Dois tipos","Vinte tipos","Oito tipos","Quatro tipos"],c:3,e:"São quatro tipos: incisivos, caninos, pré-molares e molares. Cada um tem um formato certinho para a sua tarefa."},
{n:"m",t:"A mastigação",q:"Com mais ou menos quantos anos os dentes de leite começam a cair?",a:["Com 1 ano","Com 15 anos","Com 6 anos","Com 20 anos"],c:2,e:"Por volta dos 6 anos os dentes de leite começam a cair, e a troca continua por vários anos até chegarem os 32 permanentes."},
{n:"m",t:"A mastigação",q:"Qual destes alimentos exige mais trabalho dos molares?",a:["Uma sopa batida","Um suco de laranja","Uma cenoura crua","Um iogurte"],c:2,e:"A cenoura crua é dura e precisa ser bem moída pelos molares. Sopa, suco e iogurte já estão molinhos e quase não pedem mastigação."},
{n:"m",t:"A mastigação",q:"Por que dizemos que a digestão começa na boca?",a:["Porque os dentes trituram e a saliva já começa a digerir o alimento","Porque a boca absorve os nutrientes","Porque a boca produz o suco gástrico","Porque a boca forma as fezes"],c:0,e:"Na boca acontecem duas coisas: os dentes quebram o alimento em pedaços e a saliva já começa a transformá-lo quimicamente."},
{n:"m",t:"A mastigação",q:"Por que comer muito doce aumenta o risco de cárie?",a:["Porque o açúcar deixa os dentes mais pesados","Porque o doce impede a produção de saliva","Porque o açúcar derrete a língua","Porque as bactérias da boca usam o açúcar e produzem ácido que estraga o dente"],c:3,e:"As bactérias que moram na boca adoram açúcar. Ao comê-lo, elas produzem ácido, e é esse ácido que abre buraquinhos no esmalte."},
{n:"m",t:"A mastigação",q:"Por que o dentista pede para escovarmos também a língua e as gengivas?",a:["Porque a língua tem dentes escondidos","Porque isso deixa a saliva mais gelada","Porque bactérias e restos de alimento também ficam nelas","Porque a gengiva precisa ficar mais dura"],c:2,e:"Bactérias se acumulam na língua e perto da gengiva. Escovar tudo deixa a boca mais saudável e o hálito mais fresco."},
{n:"m",t:"A mastigação",q:"Qual objeto do dia a dia trabalha de um jeito parecido com os molares?",a:["Uma tesoura","Um funil","Uma esponja","Um moedor de alimentos"],c:3,e:"Os molares moem, igual a um moedor ou a um pilão. Já a tesoura se parece mais com os incisivos, que cortam."},
{n:"m",t:"A mastigação",q:"Qual destas partes NÃO participa da mastigação?",a:["Os dentes","A língua","A saliva","O esôfago"],c:3,e:"O esôfago só entra em cena depois, para transportar o bolo alimentar. Na boca, quem trabalha são os dentes, a língua e a saliva."},
{n:"m",t:"Sistema respiratório",q:"O que acontece com as costelas e o tórax quando inspiramos fundo?",a:["Eles sobem e o tórax fica maior","Eles afundam e o tórax fica menor","Eles ficam completamente parados","Eles se fecham para prender o ar"],c:0,e:"Na inspiração as costelas sobem e o diafragma desce, então o tórax fica maior e o ar entra. Dá para sentir colocando a mão no peito."},
{n:"m",t:"Sistema respiratório",q:"Por que os pulmões têm milhões de alvéolos bem pequenininhos?",a:["Para deixar o pulmão mais pesado","Para produzir a voz","Para aumentar muito o espaço de troca de gases","Para filtrar o alimento"],c:2,e:"Muitos saquinhos pequenos criam uma superfície enorme de troca. É como abrir uma toalha dobrada: cabe muito mais contato com o sangue."},
{n:"m",t:"Sistema respiratório",q:"Qual destas partes do sistema respiratório fica DENTRO do pulmão?",a:["As fossas nasais","A laringe","A faringe","Os bronquíolos"],c:3,e:"Bronquíolos e alvéolos ficam dentro dos pulmões. Fossas nasais, faringe e laringe estão no caminho antes deles."},
{n:"m",t:"Sistema respiratório",q:"Os alvéolos ficam colados a quais vasos sanguíneos para fazer a troca de gases?",a:["Aos capilares","Às veias grossas do pescoço","Aos bronquíolos","Aos átrios"],c:0,e:"Cada alvéolo é abraçado por capilares finíssimos. Com as paredes tão fininhas, o oxigênio atravessa direto para o sangue."},
{n:"m",t:"Sistema respiratório",q:"Quando prendemos a respiração por um tempo, do que o corpo começa a sentir falta?",a:["De saliva","De oxigênio","De fezes","De bile"],c:1,e:"Sem respirar, o sangue não recebe oxigênio novo e o gás carbônico vai acumulando. Aí o corpo dá aquela vontade enorme de respirar."},
{n:"m",t:"Sistema respiratório",q:"Qual é o caminho que o ar faz para SAIR do corpo?",a:["Alvéolos, bronquíolos, brônquios, traqueia, laringe, faringe e nariz","Nariz, faringe, laringe, traqueia, alvéolos","Alvéolos, esôfago, estômago, boca","Brônquios, alvéolos, bronquíolos, nariz"],c:0,e:"Para sair, o ar faz o mesmo caminho de trás para frente: começa nos alvéolos e termina no nariz."},
{n:"m",t:"Sistema respiratório",q:"Quando estamos com o nariz entupido por causa de um resfriado, por onde acabamos respirando?",a:["Pelo esôfago","Pela boca","Pelos ouvidos","Pelo estômago"],c:1,e:"Com o nariz entupido respiramos pela boca. Funciona, mas o ar chega sem ser filtrado, aquecido e umedecido."},
{n:"m",t:"Sistema respiratório",q:"Para que serve o muco que existe dentro da traqueia?",a:["Para produzir a voz","Para prender a sujeira que passou do nariz","Para digerir o alimento","Para bombear o sangue"],c:1,e:"O muco da traqueia gruda a poeira que escapou do nariz. Depois a tosse ajuda a expulsar essa sujeira para fora."},
{n:"m",t:"Sistema respiratório",q:"Qual é a função dos brônquios?",a:["Levar o ar da traqueia para dentro de cada pulmão","Fazer a troca de gases","Produzir a voz","Empurrar o alimento"],c:0,e:"Os brônquios são os dois canos que entram nos pulmões levando o ar. Dentro deles, o caminho se ramifica em bronquíolos."},
{n:"m",t:"Sistema cardiovascular",q:"Por que as paredes das artérias são mais grossas que as das veias?",a:["Porque elas transportam ar","Porque nelas o sangue passa com mais força, empurrado pelo coração","Porque elas ficam mais longe do coração","Porque elas não têm sangue dentro"],c:1,e:"O sangue sai do coração com muita pressão, então a artéria precisa de parede reforçada, como uma mangueira de jardim mais grossa."},
{n:"m",t:"Sistema cardiovascular",q:"Para quais lugares o coração bombeia o sangue?",a:["Somente para os pulmões","Somente para o cérebro","Para os pulmões e para o resto do corpo","Somente para o estômago"],c:2,e:"O coração faz duas viagens: manda o sangue aos pulmões para pegar oxigênio e manda o sangue oxigenado para o corpo inteiro."},
{n:"m",t:"Sistema cardiovascular",q:"Por que o médico encosta o estetoscópio no peito da gente?",a:["Para medir a temperatura","Para ouvir os batimentos do coração","Para ver os dentes","Para contar as fezes"],c:1,e:"O estetoscópio deixa o médico escutar o tum-tum do coração e também o ar entrando e saindo dos pulmões."},
{n:"m",t:"Sistema cardiovascular",q:"Quando fazemos um cortinho bem pequeno no dedo e sai um pouquinho de sangue, quais vasos foram atingidos?",a:["Os capilares","Os alvéolos","Os brônquios","Os átrios"],c:0,e:"Os capilares estão em toda a pele. Como são fininhos, o sangramento é pequeno e para rapidinho."},
{n:"m",t:"Sistema cardiovascular",q:"Qual é o papel do sangue em relação ao gás carbônico?",a:["Ele produz o gás carbônico nos pulmões","Ele leva o gás carbônico das células até os pulmões","Ele transforma o gás carbônico em nutriente","Ele guarda o gás carbônico no coração"],c:1,e:"O sangue é o caminhão de coleta: recolhe o gás carbônico das células e o entrega nos pulmões, para sair na expiração."},
{n:"m",t:"Sistema cardiovascular",q:"Nas 4 cavidades do coração, quantos são átrios e quantos são ventrículos?",a:["3 átrios e 1 ventrículo","1 átrio e 3 ventrículos","2 átrios e 2 ventrículos","4 átrios e nenhum ventrículo"],c:2,e:"São 2 átrios em cima e 2 ventrículos embaixo, ou seja, 4 cavidades bem organizadas, como 4 cômodos de uma casinha."},
{n:"m",t:"Sistema cardiovascular",q:"Qual destas NÃO é uma função do sangue?",a:["Transportar oxigênio","Transportar nutrientes","Recolher o gás carbônico","Produzir a saliva"],c:3,e:"A saliva é produzida pelas glândulas salivares, não pelo sangue. O sangue transporta oxigênio e nutrientes e recolhe o gás carbônico."},
{n:"m",t:"Sistema cardiovascular",q:"Por que dizemos que o sangue faz um circuito, ou seja, um caminho fechado?",a:["Porque ele sai do coração, percorre o corpo e volta ao coração","Porque ele fica parado dentro do coração","Porque ele sai pelo nariz no fim do caminho","Porque ele é eliminado junto com as fezes"],c:0,e:"O sangue não se perde pelo caminho: sai pelas artérias, passa pelos capilares e retorna pelas veias, começando tudo de novo."},
{n:"m",t:"Sistema cardiovascular",q:"O coração é um músculo. Do que ele precisa para conseguir trabalhar sem parar?",a:["De saliva","De oxigênio e nutrientes trazidos pelo sangue","De gás carbônico","De fezes"],c:1,e:"Como todo músculo, o coração precisa de oxigênio e nutrientes. Ele recebe isso pelo próprio sangue, por vasos que alimentam suas paredes."},
{n:"d",t:"Sistema digestório",q:"O suco gástrico é bem forte. Por que ele não machuca o próprio estômago?",a:["Porque o estômago é feito de osso","Porque as paredes do estômago produzem um muco que as protege","Porque o suco gástrico só age no intestino","Porque o sangue neutraliza o suco gástrico"],c:1,e:"O estômago se protege com uma camadinha de muco, como uma capa de chuva. Sem ela, o suco gástrico machucaria a própria parede."},
{n:"d",t:"Sistema digestório",q:"Uma pessoa teve o intestino delgado muito prejudicado por uma doença. Qual função ficará mais afetada?",a:["A absorção dos nutrientes para o sangue","A produção de saliva","A entrada de ar nos pulmões","Os batimentos do coração"],c:0,e:"O intestino delgado é o órgão que absorve os nutrientes. Com ele doente, o alimento passa mas o corpo aproveita muito pouco."},
{n:"d",t:"Sistema digestório",q:"Como os nutrientes do almoço conseguem chegar até o dedão do pé?",a:["Andam sozinhos pelo intestino grosso","São absorvidos no intestino delgado, entram no sangue e o coração os bombeia até lá","Vão pela traqueia junto com o ar","São levados pela saliva"],c:1,e:"Aqui os dois sistemas se juntam: o digestório entrega os nutrientes ao sangue e o cardiovascular faz a entrega em qualquer cantinho do corpo."},
{n:"d",t:"Sistema digestório",q:"Por que às vezes ouvimos a barriga roncar?",a:["Porque o coração bate mais forte","Porque os movimentos peristálticos mexem o ar e os líquidos de dentro do tubo digestório","Porque o pulmão está sem ar","Porque os dentes estão trincando"],c:1,e:"O ronco é o barulho dos movimentos peristálticos revirando ar e líquidos. Com o estômago vazio o som fica ainda mais alto."},
{n:"d",t:"Sistema digestório",q:"Por que um alimento bem mastigado é digerido mais rápido?",a:["Porque em pedaços pequenos os sucos digestivos alcançam mais partes do alimento","Porque pedaços pequenos passam direto para o sangue na boca","Porque a mastigação esquenta o alimento","Porque o estômago só aceita alimento frio"],c:0,e:"Quanto mais picadinho, maior a área que os sucos conseguem atacar. É como dissolver açúcar em pó, que desaparece mais rápido que um cubo."},
{n:"d",t:"Sistema digestório",q:"Uma pessoa com o fígado prejudicado pode ter dificuldade em digerir qual tipo de alimento?",a:["Alimentos gordurosos","Apenas alimentos líquidos","Apenas alimentos gelados","Apenas alimentos salgados"],c:0,e:"O fígado produz a bile, que ajuda a quebrar as gorduras. Sem bile suficiente, a comida gordurosa fica bem mais difícil de digerir."},
{n:"d",t:"Sistema digestório",q:"Por que beber pouca água durante o dia pode deixar as fezes duras?",a:["Porque a água é usada para produzir suco gástrico","Porque o intestino grosso absorve a água e, com pouca água no corpo, as fezes ficam secas","Porque a água derrete as fezes no estômago","Porque a água vira bile no fígado"],c:1,e:"O intestino grosso puxa a água que sobra. Se bebemos pouco, ele puxa quase tudo e as fezes ficam secas e duras. Beber água ajuda o intestino!"},
{n:"d",t:"Sistema digestório",q:"Muita gente pensa que a digestão termina no estômago. Onde ela termina de verdade?",a:["No esôfago","No estômago mesmo","No intestino delgado","No intestino grosso"],c:2,e:"O estômago faz uma parte importante, mas quem termina o serviço é o intestino delgado, com a ajuda da bile e do suco pancreático."},
{n:"d",t:"Sistema digestório",q:"Se o intestino grosso não estiver trabalhando bem, as fezes podem sair muito líquidas. Qual função está falhando?",a:["A absorção da água","A produção de saliva","A troca de gases","A mastigação"],c:0,e:"O intestino grosso é o responsável por absorver a água. Quando ele falha, essa água sai junto com as fezes e aparece a diarreia."},
{n:"d",t:"A mastigação",q:"Se uma pessoa produzisse muito pouca saliva, o que ficaria mais difícil para ela?",a:["Formar o bolo alimentar e engolir","Respirar pelo nariz","Sentir o pulso no punho","Absorver água no intestino grosso"],c:0,e:"Sem saliva o alimento fica seco e esfarelado, e o bolo alimentar não se forma bem. Engolir vira um trabalhão."},
{n:"d",t:"A mastigação",q:"Uma criança com vários dentes doendo mastiga muito pouco a comida. O que provavelmente acontece depois?",a:["A digestão fica mais rápida","O alimento chega em pedaços grandes e o estômago e o intestino trabalham mais","A saliva deixa de ser produzida","O alimento vai para a traqueia"],c:1,e:"Sem trituração, pedaços grandes chegam ao estômago e todo o resto do sistema precisa se esforçar mais para digerir."},
{n:"d",t:"A mastigação",q:"Por que a dentição permanente tem mais dentes do que a de leite?",a:["Porque os dentes de leite se dividem em dois","Porque a boca cresce e passa a caber mais dentes de trituração no fundo","Porque as pessoas passam a comer menos","Porque os caninos desaparecem"],c:1,e:"A boca da criança é pequena e cabem 20 dentes. Quando o rosto cresce, sobra espaço no fundo para novos molares, chegando a 32."},
{n:"d",t:"A mastigação",q:"Por que não devemos abrir embalagens ou quebrar gelo com os dentes?",a:["Porque isso deixa os dentes mais brancos","Porque o esmalte pode lascar ou o dente trincar, e o esmalte não cresce de novo","Porque a saliva pode secar","Porque os dentes ficam maiores"],c:1,e:"O esmalte é duríssimo, mas não se regenera: se lascar, fica lascado. Dentes servem para mastigar comida, não para abrir coisas."},
{n:"d",t:"A mastigação",q:"Qual destes dentes NÃO tem a função de triturar o alimento?",a:["O molar de cima","O canino","O molar de baixo","O pré-molar"],c:1,e:"O canino é pontudo e serve para rasgar e perfurar, não para moer. Quem tritura são os pré-molares e os molares."},
{n:"d",t:"A mastigação",q:"Por que mastigar bem ajuda a evitar engasgos?",a:["Porque a saliva fecha a traqueia","Porque pedaços pequenos e umedecidos passam com mais facilidade pela faringe","Porque a mastigação faz a epiglote crescer","Porque a comida mastigada não precisa de esôfago"],c:1,e:"Pedaços grandes e secos podem escapar para o caminho do ar. Bem mastigado e molhadinho de saliva, o bolo alimentar desce direitinho pelo esôfago."},
{n:"d",t:"A mastigação",q:"Por que uma cárie muito avançada dói tanto?",a:["Porque a cárie chega à parte de dentro do dente, onde existem nervos","Porque o esmalte tem músculos","Porque o dente fica cheio de saliva","Porque a gengiva perde os dentes de leite"],c:0,e:"Enquanto está só no esmalte, a cárie não dói. Quando fura mais fundo e alcança a parte interna, onde há nervos, aí vem a dor."},
{n:"d",t:"A mastigação",q:"Se mastigarmos um pedaço de pão por bastante tempo, ele começa a ficar docinho. Por quê?",a:["Porque a boca esquenta o pão","Porque a saliva começa a digerir o pão e transformá-lo em açúcar","Porque o pão absorve o gás carbônico","Porque os dentes liberam açúcar"],c:1,e:"É a prova de que a digestão começa na boca: a saliva quebra o amido do pão em pedacinhos com gosto de açúcar. Vale testar em casa! 😄"},
{n:"d",t:"Sistema respiratório",q:"Por que a gente engasga quando come e fala ao mesmo tempo?",a:["Porque o esôfago fica entupido","Porque a epiglote não fecha a traqueia na hora certa e um pedaço entra no caminho do ar","Porque o pulmão para de funcionar","Porque a saliva desce pela traqueia de propósito"],c:1,e:"A faringe é caminho do ar e do alimento. Se falamos ou rimos ao engolir, a epiglote pode não fechar em tempo e o alimento entra na traqueia."},
{n:"d",t:"Sistema respiratório",q:"Por que os adultos avisam para não rir nem conversar com a boca cheia?",a:["Porque isso gasta muita saliva","Porque o alimento pode escapar para a traqueia e causar engasgo","Porque o estômago pode dobrar de tamanho","Porque o coração pode parar de bater"],c:1,e:"Rir e falar abrem a passagem do ar. Com comida na boca, aumenta a chance de o alimento entrar pela traqueia em vez do esôfago."},
{n:"d",t:"Sistema respiratório",q:"Por que respiramos mais rápido quando subimos uma escada?",a:["Porque os músculos estão trabalhando e precisam de mais oxigênio","Porque a escada tem menos ar","Porque o estômago pede mais comida","Porque o nariz fica mais frio"],c:0,e:"Subindo escada os músculos das pernas trabalham muito, gastam mais oxigênio e produzem mais gás carbônico. Aí a respiração acelera para dar conta."},
{n:"d",t:"Sistema respiratório",q:"Quando engasgamos com um pedacinho de comida, por que começamos a tossir?",a:["Porque o estômago está cheio","Porque o corpo usa a tosse para empurrar para fora o que entrou no caminho do ar","Porque a saliva parou de ser produzida","Porque o coração acelerou"],c:1,e:"A tosse é um jato de ar bem forte que o corpo dispara para expulsar o que não deveria estar na traqueia. É uma defesa automática."},
{n:"d",t:"Sistema respiratório",q:"Por que ficar em ambientes com muita fumaça faz mal aos pulmões?",a:["Porque a fumaça esfria o coração","Porque a fumaça irrita as vias respiratórias e prejudica a troca de gases nos alvéolos","Porque a fumaça entope o esôfago","Porque a fumaça aumenta o número de dentes"],c:1,e:"As partículas da fumaça machucam o caminho do ar e sujam os alvéolos. Com os alvéolos prejudicados, entra menos oxigênio no sangue."},
{n:"d",t:"Sistema respiratório",q:"Por que uma pessoa que para de respirar deixa de receber oxigênio no corpo, mesmo com o coração batendo?",a:["Porque o coração só bombeia ar","Porque o sangue pega oxigênio nos pulmões, e sem ar novo não há oxigênio para carregar","Porque o sangue fabrica oxigênio no estômago","Porque as veias se fecham"],c:1,e:"Os dois sistemas trabalham em dupla: o respiratório traz o oxigênio e o cardiovascular distribui. Se um para, o outro não dá conta sozinho."},
{n:"d",t:"Sistema respiratório",q:"Por que o ar que sai dos pulmões é mais quente e mais úmido que o ar que entrou?",a:["Porque o corpo aqueceu e umedeceu esse ar por dentro","Porque o pulmão produz vapor de gasolina","Porque o ar passou pelo estômago","Porque o coração esquentou o nariz"],c:0,e:"O nariz e as vias respiratórias esquentam e molham o ar que entra. Na saída ele já está morninho e úmido, e é por isso que embaça o espelho."},
{n:"d",t:"Sistema respiratório",q:"Em que ponto do corpo o caminho do ar e o caminho do alimento se separam?",a:["Na boca","Depois da faringe: o ar segue para a laringe e o alimento para o esôfago","No estômago","Nos alvéolos"],c:1,e:"Os dois caminhos se cruzam na faringe e se separam ali: laringe e traqueia para o ar, esôfago para o alimento. A epiglote é a porteira dessa separação."},
{n:"d",t:"Sistema respiratório",q:"Se os alvéolos de uma pessoa ficam cheios de líquido, como numa pneumonia, qual função fica prejudicada?",a:["A mastigação","A absorção de nutrientes","A troca de gases entre o ar e o sangue","A formação das fezes"],c:2,e:"Com os alvéolos alagados o oxigênio não consegue passar para o sangue. Por isso a pessoa fica com falta de ar e cansada."},
{n:"d",t:"Sistema cardiovascular",q:"Por que o coração acelera quando corremos?",a:["Porque ele fica com medo","Porque os músculos precisam de mais oxigênio e nutrientes, então o sangue tem que circular mais rápido","Porque o estômago empurra o coração","Porque o pulmão para de funcionar"],c:1,e:"Correndo, os músculos gastam muito oxigênio. O coração bate mais rápido para entregar mais sangue e recolher o gás carbônico produzido."},
{n:"d",t:"Sistema cardiovascular",q:"Por que sentimos o coração bater mais forte quando levamos um susto?",a:["Porque o corpo se prepara para reagir e manda mais sangue para os músculos","Porque o susto entope as veias","Porque o coração troca de lugar no peito","Porque o sangue vira ar"],c:0,e:"No susto o corpo entra em modo alerta e acelera o coração, para deixar os músculos prontos para correr ou reagir."},
{n:"d",t:"Sistema cardiovascular",q:"Por que o sangue precisa passar pelos pulmões antes de ser enviado ao corpo?",a:["Para ser aquecido pelo ar","Para pegar oxigênio e deixar o gás carbônico","Para receber os nutrientes do almoço","Para ser filtrado pelas fezes"],c:1,e:"Nos pulmões o sangue faz uma troca: carrega oxigênio e larga o gás carbônico. Só depois disso vale a pena distribuí-lo pelo corpo."},
{n:"d",t:"Sistema cardiovascular",q:"O coração bombeia sangue para o corpo. Ele também bombeia sangue para os pulmões?",a:["Não, o sangue vai aos pulmões sozinho","Sim, o coração manda o sangue aos pulmões para pegar oxigênio","Não, os pulmões não recebem sangue","Sim, mas só quando estamos dormindo"],c:1,e:"O coração faz dois trabalhos ao mesmo tempo: manda sangue aos pulmões para se abastecer de oxigênio e manda sangue oxigenado ao corpo todo."},
{n:"d",t:"Sistema cardiovascular",q:"Por que um cortinho na pele sangra pouco e um corte fundo pode sangrar muito?",a:["Porque na pele o sangue é mais grosso","Porque o corte raso atinge apenas capilares, e o fundo pode atingir vasos maiores","Porque o corte fundo alcança o pulmão","Porque a pele não tem sangue"],c:1,e:"Perto da superfície só existem capilares, que são fininhos. Mais fundo passam artérias e veias maiores, com muito mais sangue circulando."},
{n:"d",t:"Sistema cardiovascular",q:"Por que muitos atletas têm o coração batendo mais devagar em repouso do que uma pessoa sem treino?",a:["Porque o coração deles é feito de osso","Porque o coração treinado é mais forte e bombeia mais sangue em cada batida","Porque eles têm menos sangue no corpo","Porque eles respiram menos vezes por dia"],c:1,e:"Com o treino o coração fica mais forte e consegue empurrar mais sangue de uma vez. Assim ele precisa de menos batidas para o mesmo serviço."},
{n:"d",t:"Sistema cardiovascular",q:"Se o sangue parasse de chegar a uma parte do corpo, o que faltaria para as células dali?",a:["Oxigênio e nutrientes","Saliva e bile","Fezes e água","Gás carbônico"],c:0,e:"O sangue é quem entrega oxigênio e nutrientes. Sem essa entrega, as células ficam sem combustível e se machucam rapidinho."},
{n:"d",t:"Sistema cardiovascular",q:"Por que sentimos o pulso numa artéria e não numa veia?",a:["Porque a veia não tem sangue","Porque nas artérias o sangue é empurrado com força a cada batida do coração","Porque as veias ficam fora do corpo","Porque as artérias transportam ar"],c:1,e:"Cada batida manda uma onda de sangue com pressão pelas artérias, e essa onda é o pulso. Nas veias o sangue volta devagar, sem esse empurrão."},
{n:"d",t:"Sistema cardiovascular",q:"Depois de terminar uma corrida, por que continuamos ofegantes e com o coração acelerado por um tempo?",a:["Porque o corpo ainda precisa repor o oxigênio e eliminar o gás carbônico acumulado","Porque o coração esqueceu de desacelerar","Porque o estômago está digerindo","Porque os pulmões ficaram maiores"],c:0,e:"O corpo ainda está acertando as contas: falta repor oxigênio e tirar o gás carbônico que sobrou. Por isso a calma volta só aos pouquinhos."},
{n:"d",t:"Sistema digestório",q:"O que os nutrientes fazem depois de entrar no sangue?",a:["Voltam para o estômago","Dão energia às células e ajudam o corpo a crescer e se recuperar","Viram gás carbônico nos pulmões","São eliminados junto com as fezes"],c:1,e:"Os nutrientes são combustível e material de construção: dão energia para brincar e ajudam a fabricar novas partes do corpo."},
{n:"d",t:"Sistema digestório",q:"Se o esôfago de uma pessoa estivesse entupido, o que aconteceria?",a:["O alimento não conseguiria chegar ao estômago","O ar não chegaria aos pulmões","O coração pararia de bater","As fezes não se formariam por falta de saliva"],c:0,e:"O esôfago é o corredor entre a faringe e o estômago. Entupido, o alimento fica parado e nem começa a ser digerido no estômago."},
{n:"d",t:"Sistema digestório",q:"Por que uma refeição bem gordurosa costuma demorar mais para ser digerida?",a:["Porque a gordura não passa pelo esôfago","Porque a gordura é mais difícil de quebrar e precisa de bastante bile","Porque a gordura fica presa nos dentes","Porque a gordura vira fezes na boca"],c:1,e:"A gordura precisa primeiro ser quebrada em gotinhas pela bile e só depois é digerida. Por isso a sensação de barriga cheia dura mais tempo."},
{n:"d",t:"Sistema digestório",q:"O que a saliva faz na boca é parecido com o que qual suco faz no estômago?",a:["A bile","O suco gástrico","O muco do nariz","O sangue"],c:1,e:"Os dois são sucos digestivos que agem quimicamente no alimento: a saliva na boca e o suco gástrico no estômago."},
{n:"d",t:"Sistema digestório",q:"Por que é uma vantagem o intestino delgado ser tão comprido e enroladinho?",a:["Porque assim ele pesa mais","Porque isso dá muito mais espaço e tempo para absorver os nutrientes","Porque ele precisa alcançar os pulmões","Porque assim ele produz o suco gástrico"],c:1,e:"Comprido e enrolado, ele cabe na barriga e ainda oferece metros e metros de parede para absorver nutrientes. Nada de bom se perde."},
{n:"d",t:"Sistema digestório",q:"Por que muita gente sente dor na barriga se corre logo depois de uma refeição grande?",a:["Porque o alimento entra na traqueia","Porque durante a digestão boa parte do sangue está no sistema digestório e falta sangue para os músculos","Porque o estômago sobe até o pescoço","Porque o coração para de bater durante a digestão"],c:1,e:"Digerir dá trabalho e puxa muito sangue para o sistema digestório. Se os músculos disputam esse sangue ao mesmo tempo, vem o desconforto."},
{n:"d",t:"Sistema digestório",q:"O estômago e o intestino também são feitos de células vivas. Quem leva oxigênio até elas?",a:["A saliva","A bile","O sangue, que pegou oxigênio nos pulmões","O bolo alimentar"],c:2,e:"Todo órgão precisa de oxigênio, inclusive os da digestão. O respiratório coloca o oxigênio no sangue e o cardiovascular entrega."},
{n:"d",t:"Sistema digestório",q:"Qual afirmação sobre o intestino grosso está correta?",a:["Ele absorve a água e forma as fezes, mas não é o principal absorvedor de nutrientes","Ele é o órgão que produz o suco gástrico","Ele é o primeiro órgão do caminho do alimento","Ele faz a troca de gases com o sangue"],c:0,e:"Cuidado com essa confusão: nutrientes são absorvidos no intestino DELGADO. O grosso cuida da água e da formação das fezes."},
{n:"d",t:"Sistema digestório",q:"Ao tomar um refrigerante bem gelado, sentimos um caminho frio descendo atrás do peito. Qual órgão estamos sentindo?",a:["A traqueia","O esôfago","O coração","O pulmão"],c:1,e:"O esôfago passa pelo tórax, atrás do coração, e é ele que sentimos gelar quando engolimos algo bem frio."},
{n:"d",t:"A mastigação",q:"Por que o dentista insiste que a escovação mais importante é a da hora de dormir?",a:["Porque à noite produzimos menos saliva e as bactérias agem por mais tempo","Porque de noite os dentes crescem","Porque a escova funciona melhor no escuro","Porque dormindo não temos língua"],c:0,e:"Durante o sono a boca fica mais seca e a saliva protege menos. Se ficarem restos de comida, as bactérias têm horas livres para atacar."},
{n:"d",t:"A mastigação",q:"Qual é a diferença entre o trabalho dos dentes e o trabalho da saliva?",a:["Os dentes umedecem e a saliva corta","Os dentes quebram o alimento em pedaços e a saliva começa a transformá-lo quimicamente","Os dois só servem para deixar a comida gostosa","Os dentes absorvem nutrientes e a saliva forma as fezes"],c:1,e:"Os dentes fazem a parte de força, picando o alimento. A saliva faz a parte química, começando a desmontar o alimento por dentro."},
{n:"d",t:"A mastigação",q:"Por que perder um dente de leite muito antes da hora, por causa de uma cárie, pode ser um problema?",a:["Porque o dente permanente pode nascer fora do lugar","Porque a criança para de produzir saliva","Porque a boca deixa de ter língua","Porque os molares viram caninos"],c:0,e:"O dente de leite guarda o espaço do permanente. Se ele sai cedo demais, os vizinhos podem se mexer e o novo dente nasce torto."},
{n:"d",t:"A mastigação",q:"Ao comer uma maçã, qual é a ordem certa do trabalho dos dentes?",a:["Primeiro os molares trituram e depois os incisivos cortam","Primeiro os incisivos cortam o pedaço e depois os molares trituram","Só os caninos trabalham, do começo ao fim","Primeiro os pré-molares cortam e depois os incisivos moem"],c:1,e:"A mordida é dos incisivos, na frente. Depois a língua leva o pedaço para o fundo, onde pré-molares e molares moem tudo."},
{n:"d",t:"A mastigação",q:"Uma pessoa que respira sempre pela boca costuma ficar com a boca seca. Por que isso é ruim para os dentes?",a:["Porque a saliva ajuda a limpar os dentes e proteger contra a cárie","Porque a boca seca deixa os dentes moles","Porque sem saliva nascem mais dentes","Porque a boca seca aumenta o número de molares"],c:0,e:"A saliva lava os restinhos de comida e protege o esmalte. Com a boca seca, as bactérias ficam mais à vontade para causar cáries."},
{n:"d",t:"A mastigação",q:"João escova bem os dentes, mas nunca usa fio dental e apareceu uma cárie entre dois dentes. Qual é a explicação mais provável?",a:["A escova não alcança o espacinho entre os dentes, onde ficaram restos de alimento","A pasta de dente causa cárie","Escovar demais provoca cárie","O fio dental serve apenas para a língua"],c:0,e:"As cerdas da escova não entram entre os dentes. É exatamente ali que o fio dental trabalha, tirando os restos escondidos."},
{n:"d",t:"A mastigação",q:"Como a mastigação bem feita ajuda o intestino delgado?",a:["Ela produz suco pancreático","Quanto menores os pedaços, mais fácil os sucos digerem e mais nutrientes são absorvidos","Ela absorve os nutrientes ainda na boca","Ela forma as fezes antes do intestino grosso"],c:1,e:"Mastigar bem é ajudar toda a equipe: com o alimento bem picado, a digestão termina melhor e o intestino delgado absorve mais nutrientes."},
{n:"d",t:"A mastigação",q:"Por que uma pessoa com dor de dente forte por muito tempo pode acabar ficando fraca?",a:["Porque a dor gasta todo o oxigênio do corpo","Porque a mastigação fica prejudicada, ela come pior e recebe menos nutrientes","Porque a dor de dente para o coração","Porque a dor faz o intestino grosso desaparecer"],c:1,e:"Se dói mastigar, a pessoa evita comer ou engole sem mastigar. Assim o corpo aproveita menos nutrientes e a energia acaba faltando."},
{n:"d",t:"Sistema respiratório",q:"Por que muitas pessoas sentem falta de ar no alto de uma montanha bem alta?",a:["Porque lá o ar tem menos oxigênio do que perto do nível do mar","Porque lá não existe gás carbônico","Porque os pulmões diminuem de tamanho no frio","Porque o coração para de bombear na altitude"],c:0,e:"Quanto mais alto, mais rarefeito é o ar: em cada respirada entra menos oxigênio. O corpo compensa respirando mais rápido."},
{n:"d",t:"Sistema respiratório",q:"Por que dizemos que a respiração é uma TROCA de gases?",a:["Porque trocamos ar por água","Porque o oxigênio entra no sangue e o gás carbônico sai dele","Porque trocamos nutrientes por fezes","Porque o pulmão troca de lugar com o coração"],c:1,e:"Nos alvéolos acontece um verdadeiro escambo: o sangue recebe oxigênio e devolve gás carbônico, tudo ao mesmo tempo."},
{n:"d",t:"Sistema respiratório",q:"Por que prender a respiração por muito tempo é perigoso?",a:["Porque as células ficam sem oxigênio e o gás carbônico vai acumulando no corpo","Porque o estômago se enche de ar","Porque os dentes podem quebrar","Porque o esôfago se fecha para sempre"],c:0,e:"Sem ar novo, o sangue não repõe oxigênio e o gás carbônico sobra. Por isso o corpo dá aquela vontade irresistível de voltar a respirar."},
{n:"d",t:"Sistema respiratório",q:"Quem faz o ar entrar nos pulmões: o próprio pulmão ou os músculos da respiração?",a:["O próprio pulmão, que se enche sozinho","Os músculos da respiração, como o diafragma, que aumentam o espaço do tórax","O coração, que empurra o ar","O esôfago, que sopra o ar para dentro"],c:1,e:"Pegadinha comum: o pulmão não tem músculo próprio para se encher. Quem trabalha é o diafragma junto com os músculos das costelas."},
{n:"d",t:"Sistema respiratório",q:"Quando assoamos o nariz depois de brincar num lugar com poeira, sai muco sujinho. Isso mostra qual função do nariz?",a:["A de filtrar o ar que respiramos","A de bombear o sangue","A de digerir o alimento","A de produzir a voz"],c:0,e:"O muco e os pelinhos seguraram a poeira antes que ela chegasse aos pulmões. Aquela sujeirinha é a prova de que o filtro funcionou."},
{n:"d",t:"Sistema respiratório",q:"Depois de ficar alguns segundos embaixo da água, por que respiramos bem fundo e rápido ao voltar?",a:["Para repor o oxigênio e eliminar o gás carbônico que acumulou","Para esquentar o nariz","Para encher o estômago de ar","Para diminuir os batimentos do coração"],c:0,e:"Enquanto estávamos sem respirar, o oxigênio foi sendo gasto e o gás carbônico foi sobrando. As respiradas fundas acertam essa conta."},
{n:"d",t:"Sistema respiratório",q:"O oxigênio entrou no sangue nos alvéolos. Quem se encarrega de levá-lo até o músculo do braço?",a:["O sistema digestório","O sistema cardiovascular, com o coração bombeando o sangue","O próprio pulmão, que se estica até o braço","A saliva"],c:1,e:"O respiratório carrega o sangue de oxigênio e o cardiovascular faz a entrega. Um sistema depende do outro para o corpo funcionar."},
{n:"d",t:"Sistema respiratório",q:"Qual é o caminho do gás carbônico para sair do corpo?",a:["Das células para o sangue, do sangue para os pulmões e para fora na expiração","Das células para o estômago e depois para as fezes","Do nariz para o sangue e depois para os dentes","Do coração direto para o esôfago"],c:0,e:"O gás carbônico nasce nas células, viaja no sangue até os pulmões, atravessa para os alvéolos e sai quando soltamos o ar."},
{n:"d",t:"Sistema respiratório",q:"Ao colocar a mão na barriga e inspirar bem fundo, sentimos a barriga se mexer para fora. Por que isso acontece?",a:["Porque o estômago se enche de ar","Porque o diafragma desce e empurra os órgãos da barriga para baixo e para frente","Porque o coração muda de lugar","Porque o intestino se enche de oxigênio"],c:1,e:"O diafragma é o músculo entre o tórax e a barriga. Quando ele desce para o ar entrar, os órgãos de baixo são empurrados e a barriga se projeta."},
{n:"d",t:"Sistema cardiovascular",q:"Por que uma pessoa que perde muito sangue fica fraca e pálida?",a:["Porque sobra menos sangue para levar oxigênio e nutrientes às células","Porque o coração cresce de repente","Porque o pulmão para de respirar","Porque o intestino absorve menos água"],c:0,e:"Com menos sangue circulando, as células recebem menos oxigênio. Daí a fraqueza, a tontura e a pele mais branquinha."},
{n:"d",t:"Sistema cardiovascular",q:"O vaso que leva o sangue do coração até os pulmões é uma artéria ou uma veia?",a:["Uma veia, porque o sangue está com gás carbônico","Uma artéria, porque todo vaso que sai do coração é artéria","Um capilar, porque vai até os alvéolos","Um bronquíolo, porque entra no pulmão"],c:1,e:"O que define artéria e veia é a direção, não o gás transportado: sai do coração é artéria, volta para o coração é veia."},
{n:"d",t:"Sistema cardiovascular",q:"Por que é útil o coração ser dividido em 4 cavidades?",a:["Para caber melhor entre os pulmões","Porque os átrios recebem o sangue e os ventrículos o bombeiam, organizando as duas viagens do sangue","Para produzir 4 tipos de sangue","Para bater 4 vezes por minuto"],c:1,e:"Com 4 cômodos o coração mantém organizado o sangue que chega e o que sai, dando conta da viagem aos pulmões e da viagem ao corpo."},
{n:"d",t:"Sistema cardiovascular",q:"Por que praticar atividade física faz bem para o coração?",a:["Porque o coração é um músculo e fica mais forte e eficiente com o exercício","Porque o exercício diminui a quantidade de sangue","Porque o coração deixa de precisar de oxigênio","Porque o exercício faz o coração bater menos vezes na vida toda"],c:0,e:"Coração é músculo e músculo treinado fica mais forte. Um coração forte bombeia melhor e se cansa menos no dia a dia."},
{n:"d",t:"Sistema cardiovascular",q:"Por que num dia muito frio as mãos costumam ficar pálidas e geladas?",a:["Porque o sangue congela dentro das veias","Porque os vasos das mãos se estreitam e chega menos sangue ali, para o corpo perder menos calor","Porque o coração para de bombear para os braços","Porque as mãos não têm capilares"],c:1,e:"No frio os vasinhos da pele se apertam para o corpo economizar calor. Chegando menos sangue, as mãos esfriam e ficam mais claras."},
{n:"d",t:"Sistema cardiovascular",q:"Gustavo mediu o pulso e contou 25 batidas em 15 segundos. Quantas batidas por minuto o coração dele estava dando?",a:["25 batidas por minuto","50 batidas por minuto","100 batidas por minuto","150 batidas por minuto"],c:2,e:"Um minuto tem 60 segundos, ou seja, quatro vezes 15 segundos. Então 25 vezes 4 dá 100 batidas por minuto."},
{n:"d",t:"Sistema cardiovascular",q:"Por que é tão grave se o coração de alguém para de bater por alguns minutos?",a:["Porque o corpo esfria imediatamente","Porque o sangue para de circular e as células, principalmente as do cérebro, ficam sem oxigênio","Porque os pulmões enchem de nutrientes","Porque o estômago para de produzir suco gástrico"],c:1,e:"Sem bombeamento, o oxigênio não chega às células. O cérebro é o mais sensível de todos e precisa de socorro bem rápido."},
{n:"d",t:"Sistema cardiovascular",q:"Qual é a diferença entre o papel do pulmão e o papel do coração no transporte de oxigênio?",a:["O pulmão bombeia e o coração respira","O pulmão coloca o oxigênio no sangue e o coração bombeia esse sangue para o corpo","Os dois bombeiam sangue do mesmo jeito","O coração produz o oxigênio e o pulmão o guarda"],c:1,e:"São papéis diferentes e combinados: o pulmão abastece o sangue de oxigênio e o coração é a bomba que faz a entrega chegar longe."},
{n:"d",t:"Sistema cardiovascular",q:"As veias trazem o sangue de volta ao coração. Esse sangue está carregando o quê?",a:["Muito oxigênio recém-pegado nos alvéolos","O gás carbônico recolhido das células do corpo","Saliva vinda da boca","Fezes vindas do intestino grosso"],c:1,e:"Na volta o sangue já entregou o oxigênio e traz o gás carbônico das células, para ser eliminado nos pulmões na próxima expiração."},
];
